<?php require __DIR__.'/../../bootstrap/app.php';role_any(['admin','staff']);$db=Database::get();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);
 if(($_POST['action']??'')==='respond'){$m=trim((string)($_POST['message']??''));$pr=trim((string)($_POST['price']??''));
  if(mb_strlen($m)<5||mb_strlen($m)>2000||($pr!==''&&(!is_numeric($pr)||$pr<0)))notice('Enter a message (5-2000 characters) and a valid price, or leave the price empty.');
  else{$db->prepare("INSERT INTO quotation_responses(quotation_id,admin_id,price,message) VALUES(?,?,?,?)")->execute([$id,user()['id'],$pr===''?null:$pr,$m]);$db->prepare("UPDATE quotations SET status='quoted' WHERE id=?")->execute([$id]);audit('respond quotation','quotation',$id);notice('Response saved. The customer can see it under My quotations.');}}
 elseif($id&&in_array($_POST['status']??'',['new','reviewing','quoted','closed'],true)){$db->prepare("UPDATE quotations SET status=? WHERE id=?")->execute([$_POST['status'],$id]);audit('quotation '.$_POST['status'],'quotation',$id);notice('Quotation updated.');}
 go('admin/quotations.php');}
$rows=$db->query("SELECT q.id,q.quantity,q.message,q.status,q.created_at,u.name,u.email,p.name pname FROM quotations q LEFT JOIN users u ON u.id=q.customer_id LEFT JOIN products p ON p.id=q.product_id ORDER BY q.id DESC LIMIT 100")->fetchAll();
$ids=array_map(fn($r)=>(int)$r['id'],$rows);$resp=[];$docs=[];
if($ids){$in=implode(',',$ids);foreach($db->query("SELECT quotation_id,price,message,created_at FROM quotation_responses WHERE quotation_id IN($in) ORDER BY id DESC")->fetchAll() as $x)$resp[$x['quotation_id']][]=$x;foreach($db->query("SELECT id,quotation_id,original_name FROM uploaded_documents WHERE quotation_id IN($in)")->fetchAll() as $x)$docs[$x['quotation_id']][]=$x;}
$title='Quotations';require __DIR__.'/../../app/Views/header.php';?><section class="section"><div class="container"><div class="dash"><?php require __DIR__.'/../../app/Views/admin_nav.php';?><div><h1>Quotation requests</h1>
<?php if(!$rows):?><p>No quotation requests yet.</p><?php endif;?><?php foreach($rows as $r):?><div class="cardx mb-3"><b><?=e($r['pname'])?></b> × <?=(int)$r['quantity']?> · <?=e($r['name'])?> (<?=e($r['email'])?>) · <small><?=e($r['created_at'])?></small> · <span class="badge bg-secondary"><?=e($r['status'])?></span><p class="mt-2"><?=nl2br(e($r['message']))?></p>
<?php foreach($docs[$r['id']]??[] as $d):?><div><a href="<?=e(url('download.php?id='.(int)$d['id']))?>">📎 <?=e($d['original_name'])?></a></div><?php endforeach;?>
<?php foreach($resp[$r['id']]??[] as $x):?><div class="alert alert-light border mt-2 mb-1"><small><?=e($x['created_at'])?></small><br><?=$x['price']!==null?'<b>Price: '.e($x['price']).' ETB</b><br>':''?><?=nl2br(e($x['message']))?></div><?php endforeach;?>
<form method="post" class="mt-2"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$r['id']?>"><input type="hidden" name="action" value="respond"><input class="form-control form-control-sm mb-1" name="price" placeholder="Quoted price (ETB, optional)"><textarea class="form-control form-control-sm mb-1" name="message" rows="2" placeholder="Reply to the customer" required></textarea><button class="btn btn-sm btn-dark">Send quotation reply</button></form>
<form method="post" class="mt-1"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$r['id']?>"><?php foreach(['new','reviewing','quoted','closed'] as $s):?><button name="status" value="<?=$s?>" class="btn btn-sm btn-outline-dark" <?=$r['status']===$s?'disabled':''?>><?=$s?></button> <?php endforeach;?></form></div><?php endforeach;?></div></div></div></section><?php require __DIR__.'/../../app/Views/footer.php';?>